PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT, location TEXT, preferred_language TEXT NOT NULL DEFAULT 'en', latitude REAL, longitude REAL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preferences (profile_id TEXT PRIMARY KEY REFERENCES profile(id) ON DELETE CASCADE, notifications_enabled INTEGER NOT NULL DEFAULT 1, notification_preferences TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fields (id TEXT PRIMARY KEY, name TEXT NOT NULL, area_acres REAL NOT NULL CHECK(area_acres > 0), boundary_geojson TEXT NOT NULL, centroid_lat REAL, centroid_lon REAL, current_crop TEXT, status TEXT NOT NULL DEFAULT 'unknown', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS crop_cycles (id TEXT PRIMARY KEY, field_id TEXT NOT NULL REFERENCES fields(id) ON DELETE CASCADE, crop_name TEXT NOT NULL, planted_at TEXT NOT NULL, expected_harvest_date TEXT, current_stage TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS crop_stage_events (id TEXT PRIMARY KEY, crop_cycle_id TEXT NOT NULL REFERENCES crop_cycles(id) ON DELETE CASCADE, stage TEXT NOT NULL, occurred_at TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS field_tasks (id TEXT PRIMARY KEY, field_id TEXT NOT NULL REFERENCES fields(id) ON DELETE CASCADE, title TEXT NOT NULL, due_at TEXT, status TEXT NOT NULL DEFAULT 'open', source TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ledger_entries (id TEXT PRIMARY KEY, field_id TEXT REFERENCES fields(id) ON DELETE SET NULL, entry_type TEXT NOT NULL CHECK(entry_type IN ('income','expense')), category TEXT NOT NULL, title TEXT NOT NULL, amount_inr REAL NOT NULL CHECK(amount_inr > 0), occurred_at TEXT NOT NULL, crop_name TEXT, note TEXT, source TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','void')), created_at TEXT NOT NULL, voided_at TEXT);
CREATE TABLE IF NOT EXISTS soil_tests (id TEXT PRIMARY KEY, field_id TEXT NOT NULL REFERENCES fields(id) ON DELETE CASCADE, observed_at TEXT NOT NULL, ph REAL, organic_carbon REAL, nitrogen REAL, phosphorus REAL, potassium REAL, ec REAL, moisture_percent REAL, source TEXT NOT NULL, fetched_at TEXT NOT NULL, confidence REAL);
CREATE TABLE IF NOT EXISTS sensor_devices (id TEXT PRIMARY KEY, field_id TEXT NOT NULL REFERENCES fields(id) ON DELETE CASCADE, name TEXT NOT NULL, device_type TEXT NOT NULL, unit TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sensor_readings (id TEXT PRIMARY KEY, field_id TEXT NOT NULL REFERENCES fields(id) ON DELETE CASCADE, device_id TEXT, measurement TEXT NOT NULL, value REAL NOT NULL, unit TEXT NOT NULL, observed_at TEXT NOT NULL, source TEXT NOT NULL, fetched_at TEXT NOT NULL, confidence REAL, FOREIGN KEY(device_id) REFERENCES sensor_devices(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS field_observations (id TEXT PRIMARY KEY, field_id TEXT NOT NULL REFERENCES fields(id) ON DELETE CASCADE, observation_type TEXT NOT NULL, value REAL NOT NULL, unit TEXT NOT NULL, observed_at TEXT NOT NULL, source TEXT NOT NULL, fetched_at TEXT NOT NULL, confidence REAL);
CREATE TABLE IF NOT EXISTS irrigation_plans (id TEXT PRIMARY KEY, field_id TEXT NOT NULL REFERENCES fields(id) ON DELETE CASCADE, recommended_window_start TEXT, recommended_window_end TEXT, target_moisture_percent REAL NOT NULL, estimated_volume_liters REAL, estimated_duration_minutes REAL, status TEXT NOT NULL DEFAULT 'recommended', explanation TEXT NOT NULL, assumptions TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS irrigation_events (id TEXT PRIMARY KEY, field_id TEXT NOT NULL REFERENCES fields(id) ON DELETE CASCADE, occurred_at TEXT NOT NULL, volume_liters REAL, duration_minutes REAL, method TEXT, note TEXT, source TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reminders (id TEXT PRIMARY KEY, field_id TEXT REFERENCES fields(id) ON DELETE CASCADE, reminder_type TEXT NOT NULL, scheduled_for TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled', title TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS weather_snapshots (id TEXT PRIMARY KEY, latitude REAL NOT NULL, longitude REAL NOT NULL, provider TEXT NOT NULL, observed_at TEXT NOT NULL, fetched_at TEXT NOT NULL, payload TEXT NOT NULL, freshness_seconds INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS weather_alerts (id TEXT PRIMARY KEY, field_id TEXT REFERENCES fields(id) ON DELETE CASCADE, alert_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, severity TEXT NOT NULL, source TEXT NOT NULL, observed_at TEXT NOT NULL, fetched_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS diagnosis_requests (id TEXT PRIMARY KEY, field_id TEXT REFERENCES fields(id) ON DELETE SET NULL, status TEXT NOT NULL, provider TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS diagnoses (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES diagnosis_requests(id) ON DELETE CASCADE, label TEXT, status TEXT NOT NULL, confidence REAL, severity TEXT, treatment TEXT, provider_output TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS diagnosis_images (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES diagnosis_requests(id) ON DELETE CASCADE, path TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, checksum TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS diagnosis_feedback (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES diagnosis_requests(id) ON DELETE CASCADE, confirmed_crop TEXT, label TEXT, correctness TEXT NOT NULL CHECK(correctness IN ('confirmed','corrected','unknown')), share_for_model_improvement INTEGER NOT NULL DEFAULT 0, note TEXT, reviewer_type TEXT NOT NULL DEFAULT 'farmer', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS disease_events (id TEXT PRIMARY KEY, field_id TEXT NOT NULL REFERENCES fields(id) ON DELETE CASCADE, diagnosis_id TEXT REFERENCES diagnoses(id) ON DELETE SET NULL, occurred_at TEXT NOT NULL, note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS advisor_sessions (id TEXT PRIMARY KEY, field_id TEXT REFERENCES fields(id) ON DELETE SET NULL, language TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS advisor_messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES advisor_sessions(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, citations TEXT NOT NULL DEFAULT '[]', provider TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recommendations (id TEXT PRIMARY KEY, field_id TEXT REFERENCES fields(id) ON DELETE SET NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, field_id TEXT REFERENCES fields(id) ON DELETE CASCADE, kind TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, severity TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', dedupe_key TEXT NOT NULL UNIQUE, source TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification_deliveries (id TEXT PRIMARY KEY, alert_id TEXT NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, channel TEXT NOT NULL, status TEXT NOT NULL, attempted_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, report_type TEXT NOT NULL, from_date TEXT, to_date TEXT, status TEXT NOT NULL, input_snapshot TEXT NOT NULL, artifact TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_jobs (id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE, status TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_records (key TEXT PRIMARY KEY, request_hash TEXT NOT NULL, response_status INTEGER NOT NULL, response_body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, action TEXT NOT NULL, entity TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_crop_cycles_field ON crop_cycles(field_id, status);
CREATE INDEX IF NOT EXISTS idx_stage_events_cycle ON crop_stage_events(crop_cycle_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_sensor_readings_field ON sensor_readings(field_id, observed_at DESC);
CREATE INDEX IF NOT EXISTS idx_observations_field ON field_observations(field_id, observed_at DESC);
CREATE INDEX IF NOT EXISTS idx_weather_snapshots_location ON weather_snapshots(latitude, longitude, fetched_at DESC);
CREATE INDEX IF NOT EXISTS idx_alerts_field ON alerts(field_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_events_created ON audit_events(created_at DESC);
